import Foundation

// MARK: - IssueReporter
//
// The library imports neither `Testing` nor `XCTest`. Problems detected at
// runtime (a failed TestStore assertion, a dependency without a test value,
// an effect that threw without `catch:`) go through here.
//
// - In tests: if the test target has the `ComposableKitTestSupport` class
//   (file `ComposableKitTestSupport.swift`, generated by the testing skill),
//   the problem becomes a test failure (`Issue.record`). The class is found
//   through the Objective-C runtime, which sees every loaded image
//   (including the test bundle).
// - Outside tests: a console warning.

public struct IssueReporter: Sendable {
    public var report: @Sendable (
        _ message: String,
        _ fileID: StaticString,
        _ filePath: StaticString,
        _ line: UInt,
        _ column: UInt
    ) -> Void

    public init(
        report: @escaping @Sendable (String, StaticString, StaticString, UInt, UInt) -> Void
    ) {
        self.report = report
    }

    /// Prints the problem to the console.
    public static let runtimeWarning = IssueReporter { message, fileID, _, line, _ in
        print("⚠️ [ComposableKit] \(fileID):\(line) — \(message)")
    }

    /// Forwards to `ComposableKitTestSupport` (defined in the test target)
    /// when it exists; otherwise prints to the console.
    public static let `default` = IssueReporter { message, fileID, filePath, line, column in
        if let reporter = _testIssueReporter() {
            reporter.reportIssue(
                message,
                fileID: "\(fileID)",
                filePath: "\(filePath)",
                line: Int(line),
                column: Int(column)
            )
        } else {
            IssueReporter.runtimeWarning.report(message, fileID, filePath, line, column)
        }
    }
}

public enum IssueReporters {
    private static let storage = LockIsolated(IssueReporter.default)

    /// The reporter in use.
    public static var current: IssueReporter {
        get { storage.value }
        set { storage.setValue(newValue) }
    }
}

/// Reports an architecture misuse.
public func reportIssue(
    _ message: @autoclosure () -> String,
    fileID: StaticString = #fileID,
    filePath: StaticString = #filePath,
    line: UInt = #line,
    column: UInt = #column
) {
    IssueReporters.current.report(message(), fileID, filePath, line, column)
}

// MARK: - Bridge to the test target

/// Implemented by the `ComposableKitTestSupport` class in the test target.
@objc public protocol ComposableKitTestIssueReporting {
    static func reportIssue(_ message: String, fileID: String, filePath: String, line: Int, column: Int)

    /// Identifies the running test (`Test.current`), or `nil` outside a test.
    /// Used to give each test its own `@Shared` values. Optional: an old
    /// `ComposableKitTestSupport.swift` lacks it, and `@Shared` stays global.
    @objc optional static func currentTestScope() -> String?
}

func _testIssueReporter() -> ComposableKitTestIssueReporting.Type? {
    NSClassFromString("ComposableKitTestSupport") as? ComposableKitTestIssueReporting.Type
}

/// The running test, if any (and if `ComposableKitTestSupport.swift` can tell).
func _currentTestScope() -> String? {
    _testIssueReporter()?.currentTestScope?() ?? nil
}
